<div class="page"><div class="page-head"><div><span class="eyebrow">REVISIÓN ACTIVA</span><h1>{{$resguardo->ubicacion->Nombre}}</h1><p>{{$resguardo->periodo->Nombre}} · Revisor: {{$resguardo->empleado->Nombre}} {{$resguardo->empleado->Apellido_Paterno}}</p></div><a class="btn" href="{{route('revision.close',$resguardo)}}">Ver cierre</a></div>
<div id="message" class="alert" style="display:none"></div><div class="scan-grid"><div class="card scanner"><h2>Escanear artículo</h2><div id="reader"></div><p class="muted">Permite el acceso a la cámara. También puedes escribir el código o número de serie.</p><form id="manualForm"><div class="input-row"><input id="codigo" placeholder="Código de barras / QR / serie"><button class="btn primary">Buscar</button></div></form><div id="preview" class="scan-result" style="display:none"></div></div>
<div class="card"><div class="section-head"><h2>Artículos esperados</h2><span id="counter" class="badge green">0 / {{$items->count()}}</span></div><div class="expected-list">@foreach($items as $i)<div id="item-{{$i->FkId_Articulo}}" class="expected-item {{$i->Revisado?'reviewed':''}}"><div><strong>{{$i->articulo->Descripcion}}</strong><small>{{$i->articulo->Codigo_Barras ?: $i->articulo->N_Serie ?: 'Sin código'}}</small></div><span class="state">{{$i->Revisado?'✓ Revisado':'Pendiente'}}</span></div>@endforeach</div></div></div></div>
<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script>
<script>
const lookupUrl='{{route('revision.scan.lookup',$resguardo)}}', token='{{csrf_token()}}'; let total={{$items->count()}}, reviewed={{$items->where('Revisado',true)->count()}}; const msg=document.getElementById('message');
function show(type,text){msg.style.display='block';msg.className='alert '+type;msg.textContent=text;clearTimeout(window.mt);window.mt=setTimeout(()=>msg.style.display='none',5000)} function update(){document.getElementById('counter').textContent=reviewed+' / '+total}
function render(a,type){const p=document.getElementById('preview');p.style.display='block';p.innerHTML=`${a.imagen?`<img src="${a.imagen.startsWith('http')?a.imagen:'/storage/'+a.imagen}" class="model-img">`:`<div class="model-img model-placeholder">${a.modelo||'MODELO'}</div>`}<div><strong>${a.descripcion}</strong><div>${a.marca||''} ${a.modelo||''}</div><small>Código: ${a.codigo||'—'} · Serie: ${a.serie||'—'}</small></div>`}
async function lookup(code){if(!code)return; try{const r=await fetch(lookupUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':token,'Accept':'application/json'},body:JSON.stringify({codigo:code})});const d=await r.json();if(d.article)render(d.article,d.type);if(d.type==='reviewed'){reviewed++; const el=document.getElementById('item-'+d.article.id);if(el){el.classList.add('reviewed');el.querySelector('.state').textContent='✓ Revisado'} show('ok','Artículo revisado correctamente.');update()} else if(d.type==='already_reviewed'){show('warning',d.message);} else if(d.type==='wrong_location'){show('warning',d.message+' Ubicación registrada: '+d.actual_location+'.'); const ok=confirm('El artículo está en otra ubicación. ¿Quieres reasignarlo a '+d.expected_location+' y marcarlo como revisado?'); if(ok){const rr=await fetch('{{url('/revision/resguardos')}}/'+{{$resguardo->Id_Resguardo}}+'/reasignar/'+d.article.id,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':token,'Accept':'application/json'},body:JSON.stringify({confirmacion:true})});const rd=await rr.json();if(rd.ok){reviewed++;document.getElementById('item-'+d.article.id)?.classList.add('reviewed');show('ok',rd.message);update();}}}else if(d.type==='not_expected')show('warning',d.message);else if(d.type==='not_found')show('danger',d.message); else if(!r.ok)show('danger',d.message||'Error al consultar');}catch(e){show('danger','No fue posible consultar el artículo.')}}
document.getElementById('manualForm').addEventListener('submit',e=>{e.preventDefault();lookup(document.getElementById('codigo').value.trim());document.getElementById('codigo').value=''}); update();
if(window.Html5Qrcode){const scanner=new Html5Qrcode('reader');scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:250,height:150}},text=>{scanner.pause(true);lookup(text).finally(()=>setTimeout(()=>scanner.resume(),1200))},()=>{}).catch(()=>show('warning','No se pudo abrir la cámara. Usa HTTPS/localhost y concede permiso.'));}
</script>
